head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[checkcombobox > P > readOnly]<br/>컴포넌트의 읽기 전용 상태를 설정합니다.",
    "validation" : [
        "미설정 시 읽기 전용 상태를 적용하지 않습니다.",
        "true 설정 시 읽기 전용 상태를 적용합니다.",
        "false 설정 시 읽기 전용 상태를 적용하지 않습니다.",        
        "읽기 전용 상태일때 사용자는 컴포넌트의 아이템을 선택하거나 해제할 수 없습니다.",
        "읽기 전용 상태일때 포커스를 받을 수 있습니다.",
        "읽기 전용 상태일때 마우스/키보드 관련 이벤트도 발생합니다.",
    ]
}


scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	
};



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        readOnly : wf_sample.getObj("con_readOnly").getText(),
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onfocus", "onmousedown", "onkeydown", "onchange"])

    $c.gcm.createBasicCheckComboBox(cList, eList); 
}
